#!/usr/bin/env python3
"""Generate the mla_dec kbench suite: MLA (deepseek2, JoyAI-LLM-Flash: 32 query heads on ONE 576-dim latent cache row, V = its
first 512 dims) decode attention. base = the per-head split-K kernels the deepseek2 example builds today (old_attn.loom: g_attention_split
+ g_attention_combine at D = 576, 32 waves, ATTN_UNROLL=4, extracted from the generated program), the other variants = gen_mla_dec.py
(WMMA: all 32 heads of a token per workgroup, each latent row loaded once) with the environment of VARIANTS.

usage: gen_bench.py ROOT OUTDIR [VARIANT ...]
Timing (bench*.loom): one decode token per row at the end of a 2k / 8k / 32k context over all 40 layers (KV planes, so the cache does not
fit the 32 MB MALL), 131k over 4 layers, and 4 tokens (c4) at 8k; random cache bytes (int8 npy, generated by devlab_kbench.sh).
Correctness (test.loom): every variant against a float64 numpy reference: permuted pages, stale finite garbage past the position, several
rows / positions / a dead token, a 40k-key context (64 splits)."""
import json, os, re, shutil, subprocess, sys, tempfile
import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(sys.argv[1]) if len(sys.argv) > 1 else os.path.abspath(os.path.join(HERE, "../../../.."))
HEAD = "amdgpu.target<gfx11-generic> @w32 {subgroup_size = 32}\n\n"
QH, D, PB = 32, 576, 1152
VARIANTS = {"wmma": {}, "s32": {"MLA_DEC_S": "32"}, "s128": {"MLA_DEC_S": "128"}, "b2": {"MLA_DEC_BMIN": "2"}, "b8": {"MLA_DEC_BMIN": "8"},
            "vp4": {"MLA_DEC_VTPAD": "4"}, "s16": {"MLA_DEC_S": "16"}, "b1": {"MLA_DEC_BMIN": "1"}, "b4": {"MLA_DEC_BMIN": "4"}, "b16": {"MLA_DEC_BMIN": "16"},
            "pf1": {"MLA_DEC_PF": "1"}, "pf2": {"MLA_DEC_PF": "2"}, "pl1": {"MLA_DEC_PL": "1"},
            **{"x" + a: {"MLA_DEC_ABL": a} for a in ("empty", "noqk", "nostv", "nopv", "nosx", "nopart")}}   # x*: timing ablations (no tests)
CASES = [("256", 256, 40, 1), ("1k", 1024, 40, 1), ("2k", 2048, 40, 1), ("8k", 8192, 40, 1), ("32k", 32768, 40, 1), ("131k", 131072, 4, 1), ("c4_8k", 8192, 40, 4)]
OUT = None
_KIT = None


def kit():
    global _KIT
    if _KIT is None:
        _KIT = tempfile.mkdtemp() + "/kit"
        subprocess.run([os.path.join(ROOT, "skills/loom-port-llm/reference/apply_example.sh"), "deepseek2", _KIT], check=True, stdout=subprocess.DEVNULL)
    return _KIT


def cfg():
    return json.load(open(os.path.join(ROOT, "skills/loom-port-llm/reference/deepseek2-example/cfg.json")))


def kernels(variant, tag):
    """(text, split name, combine name) of VARIANT for case TAG."""
    if variant == "base":
        t = open(os.path.join(HERE if os.path.exists(os.path.join(HERE, "old_attn.loom")) else OUT, "old_attn.loom")).read()
        sp, co = "g_attention_split", "g_attention_combine"
    else:
        env = {k: v for k, v in os.environ.items() if not k.startswith("MLA_DEC")}
        env.update({k: v for x in variant.split("+") for k, v in VARIANTS[x].items()})
        code = f"import json,sys; sys.path.insert(0, {kit()!r}); import gen_mla_dec; print(gen_mla_dec.kernels(json.load(open({os.path.join(ROOT, 'skills/loom-port-llm/reference/deepseek2-example/cfg.json')!r}))))"
        t = subprocess.run([sys.executable, "-c", code], check=True, env=env, capture_output=True, text=True).stdout
        i = open(os.path.join(HERE if os.path.exists(os.path.join(HERE, "old_attn.loom")) else OUT, "old_attn.loom")).read()
        t = i[:i.index("\n}\n") + 3] + t   # g_kv_offset
        sp, co = "g_mla_dsplit", "g_mla_dcombine"
    s = tag.replace("_", "")
    for f in set(re.findall(r"func\.def inline @(\w+)\(", t)):
        t = re.sub(rf"@{f}\(", f"@{f}_{s}(", t)
    t = t.replace(f'export("{sp}") @{sp}(', f'export("k_split_{s}") @k_split_{s}(').replace(f'export("{co}") @{co}(', f'export("k_combine_{s}") @k_combine_{s}(')
    return t, f"k_split_{s}", f"k_combine_{s}"


def save(name, a):
    np.save(os.path.join(OUT, name + ".npy"), a)


def launches(sp, co, pfx, t, layers, ctx, pool, alen, olen, layer0=0):
    AT, OT = f"tensor<{alen}xi8>", f"tensor<{olen}xi32>"
    s = [f"""  %t = check.literal value({t}) : index
  %sliding = check.literal value(0) : i32
  %ctx = check.literal value({ctx}) : index
  %pool = check.literal value({pool}) : index
  %q = check.file.read.npy path("{pfx}_q.npy") : tensor<{t}x{QH * D}xf32>
  %info = check.file.read.npy path("{pfx}_info.npy") : tensor<{t}x4xi32>
  %orig = check.file.read.npy path("{pfx}_orig.npy") : {OT}
  %arena = check.file.read.npy path("{pfx}_arena.npy") : {AT}
  %pacc = check.generate.fill value(0.0) : tensor<{t * QH * 128 * D}xf32>
  %pml = check.generate.fill value(0.0) : tensor<{t * QH * 128 * 2}xf32>
  %o = check.generate.fill value(0.0) : tensor<{t}x{QH * D}xf32>"""]
    for L in range(layer0, layer0 + layers):
        s.append(f"""  %l{L} = check.literal value({L}) : index
  kernel.launch @{sp}[%t](%t, %l{L}, %sliding, %ctx, %pool, %q, %info, %orig, %arena, %pacc, %pml) : [index](index, index, i32, index, index, tensor<{t}x{QH * D}xf32>, tensor<{t}x4xi32>, {OT}, {AT}, tensor<{t * QH * 128 * D}xf32>, tensor<{t * QH * 128 * 2}xf32>)
  kernel.launch @{co}[%t](%t, %sliding, %info, %pacc, %pml, %q, %o) : [index](index, i32, tensor<{t}x4xi32>, tensor<{t * QH * 128 * D}xf32>, tensor<{t * QH * 128 * 2}xf32>, tensor<{t}x{QH * D}xf32>, tensor<{t}x{QH * D}xf32>)""")
    return "\n".join(s) + "\n"


def origins(maps):
    """Row records (40 bytes, the page map's byte offset at +32) then each row's int32 page map."""
    R = len(maps)
    o = [np.zeros(10 * R, np.int32)]
    off = 40 * R
    for r, m in enumerate(maps):
        o[0][10 * r + 8] = off
        o.append(np.asarray(m, np.int32)); off += 4 * len(m)
    return np.concatenate(o)


def bench_inputs(rng):
    for tag, ctx, layers, t in CASES:
        blocks = ctx // 16
        save(f"b{tag}_orig", origins([np.arange(blocks)]))
        info = np.zeros((t, 4), np.int32); info[:, 1] = ctx - t + np.arange(t); info[:, 2] = 1
        save(f"b{tag}_info", info)
        save(f"b{tag}_q", rng.uniform(-0.05, 0.05, (t, QH * D)).astype(np.float32))


def bench(variant):
    out = []
    for tag, ctx, layers, t in CASES:
        txt, sp, co = kernels(variant, tag)
        out.append(txt)
        alen = layers * ctx * PB
        out.append(f"check.case public @c{tag} {{\n" + launches(sp, co, f"b{tag}", t, layers, ctx, ctx, alen, 10 + ctx // 16) + f"  check.return\n}}\ncheck.benchmark<@c{tag}> @bm_{tag}\n")
    return out


def reference(rows_k, q, pos):
    """o [heads x 576]: softmax(q k^T * scale) over keys 0..pos of the row, V = the full row (the old kernel's 576 dims)."""
    k = rows_k[:pos + 1].astype(np.float64)
    sc = q.astype(np.float64).reshape(QH, D) @ k.T * cfg()["mla"]["scale"]
    p = np.exp(sc - sc.max(-1, keepdims=True)); p /= p.sum(-1, keepdims=True)
    return p @ k


def test_inputs(pfx, rng, rows, toks, layers, layer, ctx, stale=1000.0, qs=3.0):
    """rows: list of key counts per row (keys written 0..n-1; rest of each page stale); toks: (row, position, live)."""
    blocks = ctx // 16
    nb = [(n + 15) // 16 for n in rows]
    pool_blocks = sum(nb) + 3
    pool = pool_blocks * 16
    pages = rng.permutation(pool_blocks)
    arena = np.full((layers, pool, D), stale, np.float16)
    arena[:layer] = rng.uniform(-1, 1, (layer, pool, D)).astype(np.float16)
    if layer + 1 < layers: arena[layer + 1:] = rng.uniform(-1, 1, (layers - layer - 1, pool, D)).astype(np.float16)
    keys, maps, used = [], [], 0
    for n, b in zip(rows, nb):
        kk = rng.uniform(-1, 1, (n, D)).astype(np.float16); keys.append(kk)
        m = np.zeros(blocks, np.int32); m[:b] = pages[used:used + b]; used += b; maps.append(m)
        for j in range(b):
            seg = kk[16 * j:16 * j + 16]
            arena[layer, m[j] * 16:m[j] * 16 + len(seg)] = seg
    t = len(toks)
    info = np.zeros((t, 4), np.int32)
    for i, (r, p, lv) in enumerate(toks): info[i] = (r, p, lv, 0)
    q = (rng.uniform(-1, 1, (t, QH * D)) * qs).astype(np.float32)
    save(f"{pfx}_arena", arena.reshape(-1).view(np.int8)); save(f"{pfx}_orig", origins(maps)); save(f"{pfx}_info", info); save(f"{pfx}_q", q)
    ref = np.zeros((t, QH, D))
    for i, (r, p, lv) in enumerate(toks):
        if lv: ref[i] = reference(keys[r], q[i], p)
    return ref, t, layers * pool * PB, len(origins(maps)), pool


TESTS = [   # name, rows (keys per row), tokens (row, position, live), layers, layer, ctx
    ("tA", [2041], [(0, 2040, 1)], 4, 3, 2048),
    ("tB", [101, 18, 1, 1501], [(0, 100, 1), (1, 17, 1), (2, 0, 1), (3, 1500, 1), (0, 99, 0)], 2, 1, 2048),
    ("tC", [40001], [(0, 40000, 1)], 1, 0, 40960),
]


def tests(variants):
    rng = np.random.default_rng(7)
    out, refs = [], {}
    for name, rows, toks, layers, layer, ctx in TESTS:
        refs[name] = test_inputs(name, rng, rows, toks, layers, layer, ctx)
    for v in variants:
        if any(x.startswith("x") for x in v.split("+")):
            continue
        for name, rows, toks, layers, layer, ctx in TESTS:
            ref, t, alen, olen, pool = refs[name]
            e = ref.copy()
            if v != "base": e[:, :, 512:] = 0.0   # the WMMA kernel writes o[:, :, :512] (v_b reads those)
            save(f"{name}_{v.replace('+', '_')}_o", e.reshape(t, QH * D).astype(np.float32))
            txt, sp, co = kernels(v, f"{name}_{v.replace('+', '_')}")
            out.append(txt)
            out.append(f"check.case public @{name}_{v.replace('+', '_')} {{\n" + launches(sp, co, name, t, 1, ctx, pool, alen, olen, layer0=layer)
                       + f'  %e = check.file.read.npy path("{name}_{v.replace("+", "_")}_o.npy") : tensor<{t}x{QH * D}xf32>\n'
                       + f"  check.expect.approximate actual(%o) expected(%e) atol(5.0e-3) rtol(5.0e-3) nan(different) : tensor<{t}x{QH * D}xf32>, tensor<{t}x{QH * D}xf32>\n  check.return\n}}\n")
    return out


if __name__ == "__main__" and len(sys.argv) > 2:
    OUT = sys.argv[2]
    os.makedirs(OUT, exist_ok=True)
    vs = sys.argv[3:] or ["base", "wmma"]
    for v in vs:
        if v != "base" and not all(x in VARIANTS for x in v.split("+")):
            raise SystemExit("unknown variant " + v)
    bench_inputs(np.random.default_rng(1))
    for v in vs:
        open(os.path.join(OUT, "bench%s.loom" % ("" if v == "base" else "_" + v)), "w").write(HEAD + "\n".join(bench(v)))
    open(os.path.join(OUT, "test.loom"), "w").write(HEAD + "\n".join(tests(vs)))
    if _KIT:
        shutil.rmtree(os.path.dirname(_KIT), ignore_errors=True)
